import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import type { Persona } from '@/lib/onboarding/schemas'

/**
 * Server-side persona gate. Call at the top of any page that requires a
 * specific persona. Redirects to /dashboard with a `?reason=persona_required`
 * query param if the user's persona is not in the allowed list.
 *
 * Users with persona = null (pre-migration accounts) are allowed through to
 * preserve backward compatibility — they see all pages until they re-onboard.
 *
 * Usage:
 *   await requirePersona(['studio_owner'])
 */
export async function requirePersona(allowed: readonly Persona[]): Promise<void> {
  const supabase = await createClient()

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    redirect('/login')
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('onboarding_persona')
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { cache } from 'react'
import type { Database } from './types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export interface AuthenticatedUser {
  user: Database['public']['Tables']['profiles']['Row'] & { authId: string }
  studioId: string
  role: StudioRole
}


/**
 * Server Supabase client for Server Components, API Route Handlers, and Server Actions.
 *
 * Uses the anon key + user session cookies.
 * RLS policies apply based on the authenticated user.
 *
 * IMPORTANT: cookies() is async in Next.js 16 — must be awaited.
 */
export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // setAll called from a Server Component — cookies cannot be set
            // middleware handles session refresh
          }
        },
      },
    }
  )
}

/**
 * Cached helper that validates the session and returns the authenticated user
 * together with their primary studio context.
 *
 * Wrapped in React cache() so repeated calls within the same render tree
 * (e.g. layout + page) are deduplicated — only one round-trip per request.
 *
 * Returns null when the user is not authenticated or has no studio membership.
 */
export const getAuthenticatedUser = cache(async (): Promise<AuthenticatedUser | null> => {
  const supabase = await createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()

