}

export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(`test-send:${authUser.user.id}`)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: campaignId } = await params

  try {
    const supabase = await createClient()

    const [{ data: campaign }, { data: profile }, { data: studio }] = await Promise.all([
      supabase
        .from('marketing_campaigns')
        .select('template_subject, template_body')
        .eq('id', campaignId)
        .eq('studio_id', authUser.studioId)
        .single(),
      supabase
        .from('profiles')
        .select('first_name, email')
        .eq('id', authUser.user.id)
        .single(),
      supabase
        .from('studios')
        .select('name')
        .eq('id', authUser.studioId)
        .single(),
    ])

    if (!campaign) {
      return NextResponse.json({ error: 'Campaign not found' }, { status: 404 })
    }

    const toEmail = (profile as { first_name?: string; email?: string } | null)?.email ?? ''
    if (!toEmail) {
      return NextResponse.json({ error: 'No email address on your account' }, { status: 400 })
    }

    const firstName = (profile as { first_name?: string } | null)?.first_name ?? 'Sam'
    const studioName = (studio as { name?: string } | null)?.name ?? 'Your Studio'
    const subject = campaign.template_subject ?? '(no subject)'
    const body = campaign.template_body ?? '<p>(empty body)</p>'

    const resolvedHtml = resolveMergeTags(body, firstName, studioName)

    const key = process.env.RESEND_API_KEY
    if (!key) {
      logger.warn({ to: toEmail, campaignId }, 'test-send skipped — RESEND_API_KEY not set')
      return NextResponse.json({ ok: true, skipped: true })
    }

    const resend = new Resend(key)
    const fromEmail = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'

    const { error: sendError } = await resend.emails.send({
      from: fromEmail,
      to: toEmail,
      subject: `[Test] ${subject}`,
      html: resolvedHtml,
    })

    if (sendError) {
      logger.error({ err: sendError, to: toEmail, campaignId }, 'test-send failed')
      return NextResponse.json({ error: sendError.message ?? 'Failed to send test email' }, { status: 500 })
    }

    logger.info({ to: toEmail, campaignId }, 'marketing test send delivered')
    return NextResponse.json({ ok: true })
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error({ err }, 'campaign test-send unexpected error')
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

'use client'

import { useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type SegmentSlug =
  | 'all'
  | 'inactive_90d'
  | 'new_30d'
  | 'top_spenders'
  | 'birthday_month'
  | 'booked_next_14d'
  | 'unsubscribed'

interface SegmentCounts {
  all: number
  inactive_90d: number
  new_30d: number
  top_spenders: number
  birthday_month: number
  booked_next_14d: number
  unsubscribed: number
}

const SEGMENTS: Array<{ slug: SegmentSlug; label: string; description: string }> = [
  { slug: 'all',            label: 'All clients',          description: 'Everyone in your CRM' },
  { slug: 'inactive_90d',   label: 'Inactive 90 days',     description: 'No visit in 90 days' },
  { slug: 'new_30d',        label: 'New (last 30 days)',    description: 'First visit this month' },
  { slug: 'top_spenders',   label: 'Top spenders',         description: 'Top 20% by lifetime spend' },
  { slug: 'birthday_month', label: 'Birthday this month',  description: 'Birthdays this calendar month' },
  { slug: 'booked_next_14d',label: 'Booked next 14 days',  description: 'Upcoming appointments' },
  { slug: 'unsubscribed',   label: 'Unsubscribed',         description: 'Opted out of marketing' },
]

interface SegmentPresetChipsProps {
  activeSlug?: SegmentSlug | null
  onSelect: (slug: SegmentSlug) => void
  className?: string
}

export function SegmentPresetChips({ activeSlug, onSelect, className }: SegmentPresetChipsProps) {
  const [counts, setCounts] = useState<Partial<SegmentCounts>>({})
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    fetch('/api/marketing/segments')
      .then((r) => r.json())
      .then((json: unknown) => {
        if (cancelled) return
        if (json && typeof json === 'object' && 'data' in json) {
          setCounts((json as { data: Partial<SegmentCounts> }).data ?? {})
        }
      })
      .catch(() => {
        // non-blocking — counts just won't show
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  }, [])

  return (
    <div className={cn('flex flex-wrap gap-2', className)} role="group" aria-label="Audience segment presets">
      {SEGMENTS.map(({ slug, label, description }) => {
        const count = counts[slug]
        const isActive = activeSlug === slug

        return (
          <Button
            key={slug}
            type="button"
            variant="outline"
            size="sm"
            aria-label={`${label}${count !== undefined ? `, ${count} clients` : ''}`}
            aria-pressed={isActive}
            onClick={() => onSelect(slug)}
            className={cn(
              'h-8 gap-1.5 text-xs font-normal transition-colors',
              isActive
                ? 'bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] border-[color:var(--color-onyx)] hover:bg-[color:var(--color-onyx)]/90'
                : 'bg-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/5',
              // Unsubscribed chip is subtle — exclude action, not target
              slug === 'unsubscribed' && !isActive && 'opacity-60',
            )}
            title={description}
          >
            {label}
            {count !== undefined && !loading && (
              <span
                className={cn(
                  'inline-flex items-center justify-center rounded-full px-1.5 py-0 text-[10px] font-semibold tabular-nums min-w-[18px]',
                  isActive
                    ? 'bg-white/20 text-white'
                    : 'bg-[color:var(--color-stone)]/15 text-[color:var(--color-stone)]',
                  // Rust count badge on inactive_90d only (one Rust accent, earned)
                  slug === 'inactive_90d' && !isActive && 'bg-[color:var(--color-rust)]/10 text-[color:var(--color-rust)]',
                )}
              >
                {count.toLocaleString()}
              </span>
            )}
          </Button>
        )
      })}
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface MarketingTemplate {
  id: string
  name: string
  description: string | null
  subject_template: string
  body_template: string
  recommended_segment: string | null
  display_order: number
}

export interface TemplateSelection {
  subject: string
  body: string
  recommendedSegment: string | null
}

interface TemplateGalleryProps {
  onSelect: (selection: TemplateSelection) => void
  className?: string
}

export function TemplateGallery({ onSelect, className }: TemplateGalleryProps) {
  const [templates, setTemplates] = useState<MarketingTemplate[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    fetch('/api/marketing/templates')
      .then((r) => r.json())
      .then((json: unknown) => {
        if (cancelled) return
        if (json && typeof json === 'object' && 'data' in json) {
          setTemplates((json as { data: MarketingTemplate[] }).data ?? [])
        }
      })
      .catch(() => {
        if (!cancelled) setError('Failed to load templates')
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  }, [])

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-3 text-xs text-muted-foreground">
        <Loader2 className="h-3.5 w-3.5 animate-spin" />
        Loading templates...
      </div>
    )
  }

  if (error) {
    return <p className="py-2 text-xs text-destructive">{error}</p>
  }

  if (templates.length === 0) {
    return <p className="py-2 text-xs text-muted-foreground">No templates available.</p>
  }

  function handleSelect(t: MarketingTemplate) {
    setSelectedId(t.id)
    onSelect({
      subject: t.subject_template,
      body: t.body_template,
      recommendedSegment: t.recommended_segment,
    })
  }

  return (
    <div className={cn('grid gap-2 sm:grid-cols-2 lg:grid-cols-3', className)}>
      {templates.map((t) => (
        <div
          key={t.id}
          className={cn(
            'rounded-lg border bg-[color:var(--color-bone)] p-3 shadow-soft flex flex-col gap-2 transition-shadow hover:shadow-card',
            selectedId === t.id && 'ring-1 ring-[color:var(--color-onyx)]',
          )}
        >
          <div className="space-y-0.5">
            <p className="text-xs font-semibold text-[color:var(--color-onyx)] leading-snug">{t.name}</p>
            {t.description && (
              <p className="text-[11px] text-[color:var(--color-stone)] leading-relaxed">{t.description}</p>
            )}
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 text-xs mt-auto"
            onClick={() => handleSelect(t)}
          >
            Use template
          </Button>
        </div>
      ))}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Send } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface SendTestButtonProps {
  /** If provided, sends via `/api/marketing/campaigns/{id}/test-send`. */
  campaignId?: string
  /** Current form values — used when campaignId is not yet saved. */
  subject?: string
  body?: string
  className?: string
}

export function SendTestButton({ campaignId, subject = '', body = '', className }: SendTestButtonProps) {
  const [isSending, setIsSending] = useState(false)

  async function handleSendTest() {
    if (isSending) return
    setIsSending(true)
    try {
      const url = campaignId
        ? `/api/marketing/campaigns/${campaignId}/test-send`
        : '/api/marketing/campaigns/test-send'

      const bodyPayload = campaignId
        ? undefined
        : JSON.stringify({ subject, body, channel: 'email' })

      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: bodyPayload,
      })

      const json: unknown = await res.json()
      const message = json && typeof json === 'object' && 'error' in json
        ? String((json as { error: unknown }).error)
        : null

      if (!res.ok) {
        toast.error(message ?? 'Failed to send test email')
        return
      }

      toast.success('Test sent to your email')
    } catch (err) {
      // Ensure error never renders [object Object]
      const message = err instanceof Error ? err.message : String(err)
      toast.error(message || 'Failed to send test email')
    } finally {
      setIsSending(false)
    }
  }

  return (
    <Button
      type="button"
      variant="outline"
      size="sm"
      disabled={isSending || (!campaignId && !body)}
      onClick={handleSendTest}
      className={cn('h-7 gap-1.5 text-xs', className)}
      aria-label="Send a test email to your inbox"
    >
      <Send className="h-3 w-3" />
      {isSending ? 'Sending...' : 'Send test to me'}
    </Button>
  )
}

'use client'

import { useCallback, useRef } from 'react'
import { useEditor, EditorContent, type Editor } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Link from '@tiptap/extension-link'
import Image from '@tiptap/extension-image'
import { Extension, type Node as ProseMirrorNode } from '@tiptap/core'
import { Node as TiptapNode } from '@tiptap/core'
import { Bold, Italic, Link2, ImageIcon, Square } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { MergeTagsReference } from './MergeTagsReference'
import { cn } from '@/lib/utils'

// ─── Button block custom node ─────────────────────────────────────────────────
// Renders as <a href="..." class="btn-block"> in HTML output
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const ButtonBlock = TiptapNode.create({
  name: 'buttonBlock',
  group: 'block',
  content: 'inline*',
  defining: true,

  addAttributes() {
    return {
      href: { default: '#' },
    }
  },

  parseHTML() {
    return [{ tag: 'a.btn-block' }]
  },

  renderHTML({ HTMLAttributes }) {
    return [
      'a',
      {
        ...HTMLAttributes,
        class: 'btn-block',
        style: 'display:inline-block;background:#0f0f0f;color:#f7f7f5;padding:10px 20px;border-radius:4px;text-decoration:none;font-size:14px;',
      },
      0,
    ]
  },
})

// ─── Toolbar ──────────────────────────────────────────────────────────────────
function Toolbar({
  editor,
  onImageUpload,
}: {
  editor: Editor
  onImageUpload: () => void
}) {
  const toggleBold = () => editor.chain().focus().toggleBold().run()
  const toggleItalic = () => editor.chain().focus().toggleItalic().run()

  const setLink = () => {
    const prev = editor.getAttributes('link').href as string | undefined
    const url = window.prompt('Enter URL', prev ?? 'https://')
    if (url === null) return
    if (url === '') {
      editor.chain().focus().extendMarkRange('link').unsetLink().run()
      return
    }
    editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run()
  }

  const insertButton = () => {
    const label = window.prompt('Button label', 'Book now')
    if (!label) return
    const href = window.prompt('Button URL', 'https://')
    if (!href) return
    editor
      .chain()
      .focus()
      .insertContent({
        type: 'buttonBlock',
        attrs: { href },
        content: [{ type: 'text', text: label }],
      })
      .run()
  }

  return (
    <div className="flex items-center gap-1 border-b px-2 py-1.5 bg-[color:var(--color-bone)]">
      <ToolbarButton
        onClick={toggleBold}
        isActive={editor.isActive('bold')}
        aria-label="Bold"
      >
        <Bold className="h-3.5 w-3.5" />
      </ToolbarButton>
      <ToolbarButton
        onClick={toggleItalic}
        isActive={editor.isActive('italic')}
        aria-label="Italic"
      >
        <Italic className="h-3.5 w-3.5" />
      </ToolbarButton>
      <ToolbarButton onClick={setLink} isActive={editor.isActive('link')} aria-label="Insert link">
        <Link2 className="h-3.5 w-3.5" />
      </ToolbarButton>
      <ToolbarButton onClick={onImageUpload} isActive={false} aria-label="Insert image">
        <ImageIcon className="h-3.5 w-3.5" />
      </ToolbarButton>
      <ToolbarButton onClick={insertButton} isActive={false} aria-label="Insert button">
        <Square className="h-3.5 w-3.5" />
      </ToolbarButton>

      <div className="ml-auto">
        <MergeTagsReference />
      </div>
    </div>
  )
}

function ToolbarButton({
  children,
  onClick,
  isActive,
  'aria-label': ariaLabel,
}: {
  children: React.ReactNode
  onClick: () => void
  isActive: boolean
  'aria-label': string
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={ariaLabel}
      aria-pressed={isActive}
      className={cn(
        'inline-flex h-7 w-7 items-center justify-center rounded transition-colors',
        isActive
          ? 'bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
          : 'text-[color:var(--color-stone)] hover:bg-[color:var(--color-onyx)]/8 hover:text-[color:var(--color-onyx)]',
      )}
    >
      {children}
    </button>
  )
}

