interface RichEmailEditorProps {
  value: string
  onChange: (html: string) => void
  studioId: string
  className?: string
}

export function RichEmailEditor({ value, onChange, studioId, className }: RichEmailEditorProps) {
  const imageInputRef = useRef<HTMLInputElement>(null)
  const editorRef = useRef<Editor | null>(null)

  const editor = useEditor({
    extensions: [
      StarterKit.configure({ heading: false, codeBlock: false, blockquote: false }),
      Link.configure({ openOnClick: false, HTMLAttributes: { rel: 'noopener noreferrer' } }),
      Image.configure({ allowBase64: false }),
      ButtonBlock,
    ],
    content: value || '',
    onUpdate({ editor: e }) {
      onChange(e.getHTML())
    },
    immediatelyRender: false,
  })

  editorRef.current = editor ?? null

  const handleImageUpload = useCallback(() => {
    imageInputRef.current?.click()
  }, [])

  async function onFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file || !editorRef.current) return

    const formData = new FormData()
    formData.append('file', file)
    formData.append('studioId', studioId)
    formData.append('bucket', 'email-images')

    try {
      const res = await fetch('/api/storage/upload', { method: 'POST', body: formData })
      if (!res.ok) throw new Error('Upload failed')
      const json: unknown = await res.json()
      if (json && typeof json === 'object' && 'url' in json) {
        editorRef.current
          .chain()
          .focus()
          .setImage({ src: String((json as { url: unknown }).url) })
          .run()
      }
    } catch {
      // Non-blocking — user sees nothing inserted; no [object Object] toast
    }

    // Reset input so same file can be re-uploaded
    if (imageInputRef.current) imageInputRef.current.value = ''
  }

  if (!editor) return null

  return (
    <div className={cn('rounded-lg border shadow-soft overflow-hidden', className)}>
      <Toolbar editor={editor} onImageUpload={handleImageUpload} />

      <EditorContent
        editor={editor}
        className={cn(
          'min-h-[240px] px-4 py-3 text-sm focus-within:outline-none',
          '[&_.ProseMirror]:outline-none [&_.ProseMirror]:min-h-[200px]',
          '[&_.ProseMirror_p]:my-1 [&_.ProseMirror_a]:underline [&_.ProseMirror_a]:text-[color:var(--color-onyx)]',
          '[&_.ProseMirror_img]:max-w-full [&_.ProseMirror_img]:rounded',
        )}
      />

      <input
        ref={imageInputRef}
        type="file"
        accept="image/*"
        className="sr-only"
        aria-hidden="true"
        onChange={onFileChange}
      />
    </div>
  )
}

