// ─── Schema ───────────────────────────────────────────────────────────────────

const CampaignSchema = z.object({
  name: z.string().min(1, 'Name required').max(200),
  // Type dropdown removed — only 'manual' in v1. Field kept for API compat.
  channel: z.literal('email'),
  template_subject: z.string().max(500).optional().default(''),
  template_body: z.string().max(50000).optional().default(''),
  // Schedule
  schedule_mode: z.enum(['now', 'later']).default('now'),
  scheduled_at: z.string().optional(),
  // Recurring (RRULE or JSONB metadata fallback)
  is_recurring: z.boolean().default(false),
  recurrence_interval: z.enum(['daily', 'weekly', 'monthly']).optional(),
})

type CampaignFormValues = z.infer<typeof CampaignSchema>

// ─── AudienceFilter extended shape (M2 OR/NOT groups) ─────────────────────────
export interface AudienceFilterGroup {
  op: 'AND' | 'OR'
  conditions: Array<{
    type: 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
    value: string
  }>
}

export interface ExtendedAudienceFilter {
  groups: AudienceFilterGroup[]
  exclude: AudienceFilter
}

// Convert legacy flat filter → extended shape
function legacyToExtended(filter: AudienceFilter): ExtendedAudienceFilter {
  const conditions: AudienceFilterGroup['conditions'] = []
  if (filter.tags) filter.tags.forEach((t) => conditions.push({ type: 'tags', value: t }))
  if (filter.last_visit_days) conditions.push({ type: 'last_visit_days', value: String(filter.last_visit_days) })
  if (filter.min_spent_cents) conditions.push({ type: 'min_spent_cents', value: String(filter.min_spent_cents / 100) })
  if (filter.max_spent_cents) conditions.push({ type: 'max_spent_cents', value: String(filter.max_spent_cents / 100) })
  if (filter.location_ids) filter.location_ids.forEach((id) => conditions.push({ type: 'location_ids', value: id }))
  return { groups: [{ op: 'AND', conditions }], exclude: {} }
}

// Convert extended → legacy flat for the existing RPC (backward compat)
function extendedToLegacy(extended: ExtendedAudienceFilter): AudienceFilter {
  const first = extended.groups[0]
  if (!first) return {}
  const flat: AudienceFilter = {}
  const tags: string[] = []
  const locationIds: string[] = []
  for (const c of first.conditions) {
    switch (c.type) {
      case 'tags': tags.push(c.value); break
      case 'last_visit_days': flat.last_visit_days = parseInt(c.value, 10); break
      case 'min_spent_cents': flat.min_spent_cents = Math.round(parseFloat(c.value) * 100); break
      case 'max_spent_cents': flat.max_spent_cents = Math.round(parseFloat(c.value) * 100); break
      case 'location_ids': locationIds.push(c.value); break
    }
  }
  if (tags.length) flat.tags = tags
  if (locationIds.length) flat.location_ids = locationIds
  return flat
}

// Segment slug → flat filter preset
function segmentToFilter(slug: SegmentSlug): AudienceFilter {
  switch (slug) {
    case 'inactive_90d':     return { last_visit_days: 90 }
    case 'new_30d':          return { last_visit_days: 30 }
    case 'top_spenders':     return { min_spent_cents: 50000 }
    case 'birthday_month':   return {}
    case 'booked_next_14d':  return {}
    case 'unsubscribed':     return {}
    case 'all':
    default:                 return {}
  }
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface CampaignEditorProps {
  campaignId?: string
  defaultValues?: Partial<CampaignFormValues & { audience_filter: AudienceFilter }>
