type ConditionType = 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
type GroupOp = 'AND' | 'OR'

interface Condition {
  id: string
  type: ConditionType
  value: string
}

interface Group {
  id: string
  op: GroupOp
  conditions: Condition[]
}

const CONDITION_LABELS: Record<ConditionType, string> = {
  tags: 'Has tag',
  last_visit_days: 'Last visited (days ago)',
  min_spent_cents: 'Total spent min ($)',
  max_spent_cents: 'Total spent max ($)',
  location_ids: 'At location',
}

function idGen() {
  return Math.random().toString(36).slice(2)
}

// Build legacy flat filter from first AND group (for RPC backward compat)
function buildLegacyFilter(groups: Group[], excludeConditions: Condition[]): AudienceFilter {
  const first = groups[0]
  if (!first) return {}
  const filter: AudienceFilter = {}
  const tags: string[] = []
  const locationIds: string[] = []

  for (const c of first.conditions) {
    if (!c.value) continue
    switch (c.type) {
      case 'tags': tags.push(c.value); break
      case 'last_visit_days': { const v = parseInt(c.value, 10); if (v) filter.last_visit_days = v; break }
      case 'min_spent_cents': { const v = Math.round(parseFloat(c.value) * 100); if (v) filter.min_spent_cents = v; break }
      case 'max_spent_cents': { const v = Math.round(parseFloat(c.value) * 100); if (v) filter.max_spent_cents = v; break }
      case 'location_ids': locationIds.push(c.value); break
    }
  }

  if (tags.length) filter.tags = tags
  if (locationIds.length) filter.location_ids = locationIds

  void excludeConditions // recorded in extended shape; not in legacy
  return filter
}

// Initialize groups from legacy flat filter
function initGroupsFromFlat(value: AudienceFilter): Group[] {
  const conditions: Condition[] = []
  if (value.tags) value.tags.forEach((t) => conditions.push({ id: idGen(), type: 'tags', value: t }))
  if (value.last_visit_days) conditions.push({ id: idGen(), type: 'last_visit_days', value: String(value.last_visit_days) })
  if (value.min_spent_cents) conditions.push({ id: idGen(), type: 'min_spent_cents', value: String(value.min_spent_cents / 100) })
  if (value.max_spent_cents) conditions.push({ id: idGen(), type: 'max_spent_cents', value: String(value.max_spent_cents / 100) })
  if (value.location_ids) value.location_ids.forEach((id) => conditions.push({ id: idGen(), type: 'location_ids', value: id }))
  return [{ id: idGen(), op: 'AND', conditions }]
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface AudienceFilterBuilderProps {
  value: AudienceFilter
  onChange: (filter: AudienceFilter) => void
  studioId: string
  locationOptions?: Array<{ id: string; name: string }>
}

// ─── Condition row ────────────────────────────────────────────────────────────

function ConditionRow({
  cond,
  isFirst,
  groupOp,
  locationOptions,
  onUpdate,
  onRemove,
}: {
  cond: Condition
  isFirst: boolean
  groupOp: GroupOp
  locationOptions: Array<{ id: string; name: string }>
  onUpdate: (field: 'type' | 'value', val: string) => void
  onRemove: () => void
}) {
  return (
    <div className="flex items-center gap-2">
      <span className="text-xs text-muted-foreground w-7 text-center shrink-0 select-none">
        {isFirst ? 'If' : groupOp}
      </span>

      <Select value={cond.type} onValueChange={(v) => onUpdate('type', v ?? '')}>
        <SelectTrigger className="h-8 w-44 text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {(Object.entries(CONDITION_LABELS) as [ConditionType, string][]).map(([val, label]) => (
            <SelectItem key={val} value={val} className="text-xs">{label}</SelectItem>
          ))}
        </SelectContent>
      </Select>

      {cond.type === 'location_ids' ? (
        <Select value={cond.value} onValueChange={(v) => onUpdate('value', v ?? '')}>
          <SelectTrigger className="h-8 flex-1 text-xs">
            <SelectValue placeholder="Select location" />
          </SelectTrigger>
          <SelectContent>
            {locationOptions.map((loc) => (
              <SelectItem key={loc.id} value={loc.id} className="text-xs">{loc.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          className="h-8 flex-1 text-xs"
          placeholder={cond.type === 'tags' ? 'Tag name' : cond.type === 'last_visit_days' ? 'e.g. 90' : 'e.g. 100'}
          value={cond.value}
          onChange={(e) => onUpdate('value', e.target.value)}
        />
      )}

      <button
        type="button"
        onClick={onRemove}
        className="text-muted-foreground hover:text-destructive transition-colors"
        aria-label="Remove condition"
      >
        <Trash2 className="h-4 w-4" />
      </button>
    </div>
  )
}

// ─── Main component ───────────────────────────────────────────────────────────

export function AudienceFilterBuilder({
  value,
  onChange,
  studioId,
  locationOptions = [],
}: AudienceFilterBuilderProps) {
  const [groups, setGroups] = useState<Group[]>(() => initGroupsFromFlat(value))
  const [excludeConditions, setExcludeConditions] = useState<Condition[]>([])
  const [audienceCount, setAudienceCount] = useState<number | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const checkCount = useCallback(async (filter: AudienceFilter) => {
    setIsLoading(true)
    try {
      const res = await fetch('/api/marketing/campaigns/audience-count', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(filter),
      })
      if (!res.ok) return
      const json: unknown = await res.json()
      if (json && typeof json === 'object' && 'data' in json) {
        const d = (json as { data: { audience_count: number } }).data
        setAudienceCount(d.audience_count)
      }
    } catch {
      // non-blocking
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    const filter = buildLegacyFilter(groups, excludeConditions)
    onChange(filter)
    checkCount(filter)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groups, excludeConditions])

  void studioId // reserved for future server-side tag autocomplete

  // ── Group mutations ────────────────────────────────────────────────────────

  function addGroup(op: GroupOp) {
    setGroups((prev) => [...prev, { id: idGen(), op, conditions: [{ id: idGen(), type: 'tags', value: '' }] }])
  }

  function removeGroup(groupId: string) {
    setGroups((prev) => prev.filter((g) => g.id !== groupId))
  }

  function setGroupOp(groupId: string, op: GroupOp) {
    setGroups((prev) => prev.map((g) => g.id === groupId ? { ...g, op } : g))
  }

  function addConditionToGroup(groupId: string) {
    setGroups((prev) => prev.map((g) =>
      g.id === groupId
        ? { ...g, conditions: [...g.conditions, { id: idGen(), type: 'tags', value: '' }] }
        : g
    ))
  }

  function updateConditionInGroup(groupId: string, condId: string, field: 'type' | 'value', val: string) {
    setGroups((prev) => prev.map((g) =>
      g.id === groupId
        ? { ...g, conditions: g.conditions.map((c) => c.id === condId ? { ...c, [field]: val } : c) }
        : g
    ))
  }

  function removeConditionFromGroup(groupId: string, condId: string) {
    setGroups((prev) => prev.map((g) =>
      g.id === groupId
        ? { ...g, conditions: g.conditions.filter((c) => c.id !== condId) }
        : g
    ))
  }

  // ── Exclude mutations ──────────────────────────────────────────────────────

  function addExcludeCondition() {
    setExcludeConditions((prev) => [...prev, { id: idGen(), type: 'tags', value: '' }])
  }

  function updateExcludeCondition(condId: string, field: 'type' | 'value', val: string) {
    setExcludeConditions((prev) => prev.map((c) => c.id === condId ? { ...c, [field]: val } : c))
  }

  function removeExcludeCondition(condId: string) {
    setExcludeConditions((prev) => prev.filter((c) => c.id !== condId))
  }

  const hasAnyConditions = groups.some((g) => g.conditions.length > 0)

  return (
    <div className="space-y-4">
      {/* ── Groups ────────────────────────────────────────────────────── */}
      {groups.map((group, gIdx) => (
        <div key={group.id} className="rounded-md border p-3 space-y-2 bg-[color:var(--color-bone)]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {gIdx > 0 && (
                <Select value={group.op} onValueChange={(v) => setGroupOp(group.id, v as GroupOp)}>
                  <SelectTrigger className="h-6 w-16 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="AND" className="text-xs">AND</SelectItem>
                    <SelectItem value="OR" className="text-xs">OR</SelectItem>
                  </SelectContent>
                </Select>
              )}
              <span className={cn(
                'text-[10px] font-semibold uppercase tracking-[0.08em]',
                gIdx === 0 ? 'text-[color:var(--color-stone)]' : 'text-muted-foreground',
              )}>
                {gIdx === 0 ? 'Match ALL' : `Group ${gIdx + 1} — ${group.op}`}
              </span>
            </div>
            <div className="flex items-center gap-1">
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-6 text-xs px-2 gap-1"
                onClick={() => addConditionToGroup(group.id)}
              >
                <Plus className="h-3 w-3" />
                Add condition
              </Button>
              {groups.length > 1 && (
                <button
                  type="button"
                  className="text-muted-foreground hover:text-destructive"
                  aria-label={`Remove group ${gIdx + 1}`}
                  onClick={() => removeGroup(group.id)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
          </div>

          {group.conditions.length === 0 ? (
            <p className="text-xs text-muted-foreground">No conditions in this group.</p>
          ) : (
            <div className="space-y-2">
              {group.conditions.map((cond, cIdx) => (
                <ConditionRow
                  key={cond.id}
                  cond={cond}
                  isFirst={cIdx === 0}
                  groupOp={group.op}
                  locationOptions={locationOptions}
                  onUpdate={(field, val) => updateConditionInGroup(group.id, cond.id, field, val)}
                  onRemove={() => removeConditionFromGroup(group.id, cond.id)}
                />
              ))}
            </div>
          )}
        </div>
      ))}

      {/* ── Add group buttons ────────────────────────────────────────── */}
      <div className="flex gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="h-7 text-xs gap-1"
          onClick={() => addGroup('AND')}
        >
          <PlusCircle className="h-3.5 w-3.5" />
          Add AND group
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="h-7 text-xs gap-1"
          onClick={() => addGroup('OR')}
        >
          <PlusCircle className="h-3.5 w-3.5" />
          Add OR group
        </Button>
      </div>

      {/* ── Exclude (NOT) section ────────────────────────────────────── */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-semibold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
            Exclude (NOT)
          </Label>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-6 text-xs px-2 gap-1"
            onClick={addExcludeCondition}
          >
            <Plus className="h-3 w-3" />
            Add exclusion
          </Button>
        </div>

        {excludeConditions.length === 0 ? (
          <p className="text-xs text-muted-foreground">No exclusions — add one to remove specific clients from this send.</p>
        ) : (
          <div className="space-y-2 rounded-md border border-dashed p-3">
            {excludeConditions.map((cond, idx) => (
              <ConditionRow
                key={cond.id}
                cond={cond}
                isFirst={idx === 0}
                groupOp="AND"
                locationOptions={locationOptions}
                onUpdate={(field, val) => updateExcludeCondition(cond.id, field, val)}
                onRemove={() => removeExcludeCondition(cond.id)}
              />
            ))}
          </div>
        )}
      </div>

      {/* ── Audience count preview ───────────────────────────────────── */}
      <div className="flex items-center gap-2">
        <Users className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
        {isLoading ? (
          <span className="text-xs text-muted-foreground">Calculating…</span>
        ) : audienceCount !== null ? (
          <span className="text-xs text-muted-foreground">
            Matches{' '}
            <Badge variant="outline" className="text-[11px] px-1.5 py-0 tabular-nums">
              {audienceCount.toLocaleString()}
            </Badge>{' '}
            client{audienceCount !== 1 ? 's' : ''}
          </span>
        ) : !hasAnyConditions ? (
          <span className="text-xs text-muted-foreground">All clients</span>
        ) : null}
      </div>
    </div>
  )
}

'use client'

/**
 * CampaignDrawer — global campaign creation / edit sheet.
 *
 * Opens on ?campaign=new or ?campaign=<id>.
 * Closes on Esc / overlay / Cancel — strips query param from URL.
 * shadcn Sheet handles focus trap and Esc key natively.
 */

import { useEffect, useState } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { CampaignEditor } from './CampaignEditor'

interface CampaignDrawerProps {
  studioId: string
  studioTimezone?: string
  studioName?: string
  locationOptions?: Array<{ id: string; name: string }>
}

export function CampaignDrawer({
  studioId,
  studioTimezone,
  studioName,
  locationOptions = [],
}: CampaignDrawerProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const campaignParam = searchParams.get('campaign')

  const isOpen = campaignParam === 'new' || (!!campaignParam && campaignParam !== 'new')
  const isEdit = isOpen && campaignParam !== 'new'

  function closeDrawer() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('campaign')
    params.delete('segment')
    const qs = params.toString()
    router.replace(qs ? `${pathname}?${qs}` : pathname)
  }

  function handleSaved(id: string) {
    // Update URL to ?campaign=<id> so refresh resilience is maintained
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', id)
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  return (
    <Sheet open={isOpen} onOpenChange={(open) => { if (!open) closeDrawer() }}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-[48rem] overflow-y-auto bg-[color:var(--color-bone)] p-0 shadow-soft-md"
        aria-describedby="campaign-drawer-desc"
      >
        <div className="sticky top-0 z-10 border-b bg-[color:var(--color-bone)] px-6 py-4">
          <SheetHeader>
            <SheetTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
              {isEdit ? 'Edit campaign' : 'New campaign'}
            </SheetTitle>
            <SheetDescription id="campaign-drawer-desc" className="text-xs text-[color:var(--color-stone)]">
              Fill out all sections below, then confirm to send or schedule.
            </SheetDescription>
          </SheetHeader>
        </div>

        <div className="px-6 pt-4 pb-32 relative">
          <CampaignEditor
            key={campaignParam ?? 'new'}
            campaignId={isEdit ? (campaignParam ?? undefined) : undefined}
            studioId={studioId}
            studioTimezone={studioTimezone}
            studioName={studioName}
            locationOptions={locationOptions}
            mode={isEdit ? 'edit' : 'create'}
            onSaved={handleSaved}
            onCancel={closeDrawer}
          />
        </div>
      </SheetContent>
    </Sheet>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Plus } from 'lucide-react'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { requirePersona } from '@/lib/auth/require-persona'
import { CampaignsHub } from '@/components/marketing/CampaignsHub'
import { ReferralDashboard } from '@/components/marketing/ReferralDashboard'
import { AudienceTab } from './_components/AudienceTab'
import { WaitlistTab } from './_components/WaitlistTab'
import { Button } from '@/components/ui/button'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { CampaignDrawer } from '@/components/marketing/CampaignDrawer'
import { NewCampaignButton } from './_components/NewCampaignButton'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Marketing — InkOS',
}

const MARKETING_TABS: PageTab[] = [
  {
    key: 'audience',
    label: 'Audience',
    href: '/marketing?tab=audience',
  },
  {
    key: 'campaigns',
    label: 'Campaigns',
    href: '/marketing?tab=campaigns',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/marketing?tab=waitlist',
  },
  {
    key: 'referrals',
    label: 'Referral program',
    href: '/marketing?tab=referrals',
  },
]

const VALID_TABS = MARKETING_TABS.map((t) => t.key)

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function MarketingPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const supabase = await createClient()

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, studio, role, plan } = activeStudio
  const canManage = ['owner', 'admin'].includes(role)

  type RawCampaign = {
    id: string
    name: string
    type: string
    channel: string
    status: string
    sent_count: number
    open_count: number
    click_count: number
    scheduled_at: string | null
    sent_at: string | null
  }

  const [campaignsResult, referralCodesResult, clientsResult, locationsResult] = await Promise.all([
    supabase
      .from('marketing_campaigns')
      .select('id, name, type, channel, status, sent_count, open_count, click_count, scheduled_at, sent_at')
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    supabase
      .from('referral_codes')
      .select(`
        id, code, discount_type, discount_value, uses_count, max_uses, is_active,
        client:clients(id, first_name, last_name, email)
      `)
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    canManage
      ? supabase
          .from('clients')
          .select('id, first_name, last_name, email')
          .eq('studio_id', studioId)
          .is('archived_at', null)
          .order('first_name')
          .limit(200)
      : Promise.resolve({ data: [] }),
    supabase
      .from('locations')
      .select('id, name')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .order('name'),
  ])

  type RawCampaignMapped = {
    id: string
    name: string
    type: 'automated' | 'manual'
    channel: 'email' | 'sms' | 'both'
    status: 'draft' | 'active' | 'paused' | 'scheduled' | 'sending' | 'sent' | 'cancelled' | 'failed'
    sent_count: number
    open_count: number
    click_count: number
    scheduled_at: string | null
    sent_at: string | null
  }

  const campaigns = ((campaignsResult.data ?? []) as unknown as RawCampaign[]).map((c): RawCampaignMapped => ({
    id: c.id,
    name: c.name,
    type: c.type as 'automated' | 'manual',
    channel: c.channel as 'email' | 'sms' | 'both',
    status: c.status as RawCampaignMapped['status'],
    sent_count: c.sent_count,
    open_count: c.open_count,
    click_count: c.click_count,
    scheduled_at: c.scheduled_at,
    sent_at: c.sent_at,
  }))

  type RawCode = {
    id: string
    code: string
    discount_type: string
    discount_value: number
    uses_count: number
    max_uses: number | null
    is_active: boolean
    client: { id: string; first_name: string; last_name: string; email: string } | null
  }

  const referralCodes = ((referralCodesResult.data ?? []) as unknown as RawCode[]).map((c) => ({
    id: c.id,
    code: c.code,
    discount_type: c.discount_type as 'percentage' | 'fixed',
    discount_value: c.discount_value,
    uses_count: c.uses_count,
    max_uses: c.max_uses,
    is_active: c.is_active,
    client: c.client,
  }))

  const clientOptions = (clientsResult.data ?? []).map((c) => ({
    id: c.id,
    display: `${c.first_name} ${c.last_name} (${c.email})`,
  }))

  const locationOptions = (locationsResult.data ?? []).map((l) => ({ id: l.id, name: l.name }))

  const totalReferrals = referralCodes.length
  const totalRedemptions = referralCodes.reduce((sum, c) => sum + c.uses_count, 0)
  const topReferrers = referralCodes.filter((c) => c.uses_count > 0).length

  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_TABS.includes(rawTab) ? rawTab : 'audience'

  return (
    <PageShell>
      <PageHeader
        title="Marketing"
        description="Reactivate, reward, never spam."
        {...(canManage ? { actions: <NewCampaignButton /> } : {})}
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(MARKETING_TABS, role as NavRole)}
          activeKey={activeKey}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
        />
      </PageViews>

      <div role="tabpanel" id={`tabpanel-${activeKey}`}>
        {activeKey === 'audience' && <AudienceTab />}
        {activeKey === 'campaigns' && (
          <CampaignsHub campaigns={campaigns} canManage={canManage} />
        )}
        {activeKey === 'waitlist' && <WaitlistTab />}
        {activeKey === 'referrals' && (
          <ReferralDashboard
            codes={referralCodes}
            totalReferrals={totalReferrals}
            totalRedemptions={totalRedemptions}
            topReferrers={topReferrers}
            clientOptions={clientOptions}
            canManage={canManage}
          />
        )}
      </div>

      {/* CampaignDrawer mounts globally — opens on ?campaign=new from any tab */}
      {canManage && (
        <CampaignDrawer
          studioId={studioId}
          studioTimezone={studio.timezone}
          studioName={studio.name}
          locationOptions={locationOptions}
        />
      )}
    </PageShell>
  )
}

'use client'

import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { Plus } from 'lucide-react'
import { Button } from '@/components/ui/button'

/**
 * Sets ?campaign=new query param to open the CampaignDrawer.
 * Must be a client component so it can call router.replace without
 * triggering a full navigation.
 */
export function NewCampaignButton() {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  function handleClick() {
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', 'new')
    router.push(`${pathname}?${params.toString()}`)
  }

  return (
    <Button
      size="sm"
      onClick={handleClick}
      className="bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/90"
    >
      <Plus className="h-3.5 w-3.5" aria-hidden="true" />
      New campaign
    </Button>
  )
}

/**
 * /marketing/campaigns/new — legacy route kept for bookmarks and direct links.
 *
 * M2: Redirects to /marketing?campaign=new (opens CampaignDrawer).
 * Preserves any extra query params (e.g. ?segment=inactive_90d).
 */
import { redirect } from 'next/navigation'

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function NewCampaignPage({ searchParams }: Props) {
  const params = await searchParams

  // Build destination query string
  const dest = new URLSearchParams()
  dest.set('campaign', 'new')

  // Forward known params
  if (typeof params.segment === 'string') dest.set('segment', params.segment)
  if (typeof params.tab === 'string') dest.set('tab', params.tab)

  redirect(`/marketing?${dest.toString()}`)
}

