import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()

    // get_marketing_segment_counts is seeded by M6 migration.
    // Types will be regenerated after that migration — cast until then.
    const { data, error } = await supabase
      .from('marketing_campaigns' as 'marketing_campaigns') // table exists; rpc cast below
      .select('id')
      .eq('studio_id', authUser.studioId)
      .limit(0)
      .then(() =>
        // Call raw RPC with SQL function approach
        supabase.rpc('get_campaign_audience_count', {
          p_studio_id: authUser.studioId,
          p_filter: {},
        } as Parameters<typeof supabase.rpc>[1])
      )
      .catch(() => ({ data: null, error: new Error('rpc not available') }))

    // If the dedicated segment RPC isn't available, return zeroed counts
    // so the UI still renders without crashing.
    void data
    void error

    // Try the actual RPC — ignore type error since it's a schema gap
    type SegmentCounts = {
      all: number
      inactive_90d: number
      new_30d: number
      top_spenders: number
      birthday_month: number
      booked_next_14d: number
      unsubscribed: number
    }

    // Use a direct Postgres REST call via the existing client
    const rpcResult = await fetch(
      `${process.env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/rpc/get_marketing_segment_counts`,
      {
        method: 'POST',
        headers: {
          apikey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? '',
          'Content-Type': 'application/json',
          Authorization: `Bearer ${process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? ''}`,
        },
        body: JSON.stringify({ p_studio_id: authUser.studioId }),
      }
    )

    if (!rpcResult.ok) {
      // RPC not yet seeded — return empty counts
      const empty: SegmentCounts = { all: 0, inactive_90d: 0, new_30d: 0, top_spenders: 0, birthday_month: 0, booked_next_14d: 0, unsubscribed: 0 }
      return NextResponse.json({ data: empty })
    }

    const counts = (await rpcResult.json()) as SegmentCounts
    return NextResponse.json({ data: counts })
  } catch (err) {
    logger.error({ err }, 'segment counts unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import type { SupabaseClient } from '@supabase/supabase-js'

interface SegmentCounts {
  all: number
  inactive_90d: number
  new_30d: number
  top_spenders: number
  birthday_month: number
  booked_next_14d: number
  unsubscribed: number
}

// The get_marketing_segment_counts RPC is seeded by the M6 migration.
// Until pnpm db:types is re-run after that migration, the generated types
// don't include it. This helper casts the client to bypass the type check.
async function callSegmentCountsRpc(
  supabase: SupabaseClient,
  studioId: string
): Promise<{ data: SegmentCounts | null; error: Error | null }> {
  // Cast to unknown first to sidestep the generated function registry
  const client = supabase as unknown as {
    rpc: (fn: string, args: Record<string, string>) => Promise<{ data: SegmentCounts | null; error: { message: string } | null }>
  }
  const result = await client.rpc('get_marketing_segment_counts', { p_studio_id: studioId })
  return {
    data: result.data,
    error: result.error ? new Error(result.error.message) : null,
  }
}

const EMPTY_COUNTS: SegmentCounts = {
  all: 0,
  inactive_90d: 0,
  new_30d: 0,
  top_spenders: 0,
  birthday_month: 0,
  booked_next_14d: 0,
  unsubscribed: 0,
}

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await callSegmentCountsRpc(supabase, authUser.studioId)

    if (error) {
      logger.warn({ err: error, studioId: authUser.studioId }, 'segment counts rpc failed — returning empty counts')
      return NextResponse.json({ data: EMPTY_COUNTS })
    }

    return NextResponse.json({ data: data ?? EMPTY_COUNTS })
  } catch (err) {
    logger.error({ err }, 'segment counts unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * Shared marketing types — hand-maintained until pnpm db:types regeneration
 * includes these interface shapes.
 *
 * NOTE: AudienceFilter was previously in lib/supabase/types.ts but was
 * removed during M6 schema regeneration. Defined here to avoid scatter.
 */

// Legacy flat audience filter shape — supported by get_campaign_audience_count RPC
export interface AudienceFilter {
  tags?: string[]
  last_visit_days?: number
  min_spent_cents?: number
  max_spent_cents?: number
  location_ids?: string[]
}

// M2 extended shape with OR/NOT groups — backward compat via legacy serialization
export interface AudienceFilterGroup {
  op: 'AND' | 'OR'
  conditions: Array<{
    type: 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
    value: string
  }>
}

export interface ExtendedAudienceFilter {
  groups: AudienceFilterGroup[]
  exclude: AudienceFilter
}

// Marketing campaign status (derived — never set by UI)
export type CampaignStatus =
  | 'draft'
  | 'scheduled'
  | 'sending'
  | 'sent'
  | 'paused'
  | 'active'
  | 'cancelled'
  | 'failed'

export type CampaignType = 'manual' | 'automated'
export type CampaignChannel = 'email' | 'sms' | 'both'

