import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface MarketingTemplate {
  id: string
  name: string
  description: string | null
  subject_template: string
  body_template: string
  recommended_segment: string | null
  display_order: number
}

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()

    // marketing_templates table is seeded by M6 migration.
    // The generated types will include it after pnpm db:types — cast until then.
    const client = supabase as unknown as {
      from: (table: string) => {
        select: (cols: string) => {
          order: (col: string, opts: { ascending: boolean }) => Promise<{ data: MarketingTemplate[] | null; error: { message: string } | null }>
        }
      }
    }

    const { data, error } = await client
      .from('marketing_templates')
      .select('id, name, description, subject_template, body_template, recommended_segment, display_order')
      .order('display_order', { ascending: true })

    if (error) {
      logger.warn({ err: error }, 'marketing templates fetch failed — returning empty')
      return NextResponse.json({ data: [] })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'marketing templates unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

