  studioTimezone,
  locationOptions = [],
  mode: _mode,
  onSaved,
  onCancel,
}: CampaignEditorProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [isSaving, setIsSaving] = useState(false)
  const [savedId, setSavedId] = useState<string | null>(campaignId ?? null)
  const [showConfirm, setShowConfirm] = useState(false)

  const [audienceFilter, setAudienceFilter] = useState<AudienceFilter>(
    (defaultValues?.audience_filter as AudienceFilter) ?? {}
  )
  const [extendedFilter, setExtendedFilter] = useState<ExtendedAudienceFilter>(
    legacyToExtended((defaultValues?.audience_filter as AudienceFilter) ?? {})
  )
  const [activeSegment, setActiveSegment] = useState<SegmentSlug | null>(null)
  const [audienceCount, setAudienceCount] = useState<number | null>(null)
  const [countLoading, setCountLoading] = useState(false)

  const { register, handleSubmit, control, watch, setValue, formState: { errors } } = useForm<CampaignFormValues>({
    resolver: zodResolver(CampaignSchema),
    defaultValues: {
      name: defaultValues?.name ?? '',
      channel: 'email',
      template_subject: defaultValues?.template_subject ?? '',
      template_body: defaultValues?.template_body ?? '',
      schedule_mode: 'now',
      scheduled_at: defaultValues?.scheduled_at ?? '',
      is_recurring: false,
      recurrence_interval: 'weekly',
    },
  })

  const scheduleMode = watch('schedule_mode')
  const isRecurring = watch('is_recurring')
  const templateBody = watch('template_body')
  const templateSubject = watch('template_subject')

  // Fetch audience count whenever extended filter changes
  useEffect(() => {
    const flat = extendedToLegacy(extendedFilter)
    setAudienceFilter(flat)
    setCountLoading(true)

    const ctrl = new AbortController()
    fetch('/api/marketing/campaigns/audience-count', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(flat),
      signal: ctrl.signal,
    })
      .then((r) => r.json())
      .then((json: unknown) => {
        if (json && typeof json === 'object' && 'data' in json) {
          const d = (json as { data: { audience_count: number } }).data
          setAudienceCount(d.audience_count)
        }
      })
      .catch(() => {/* aborted or network error */})
      .finally(() => setCountLoading(false))

    return () => ctrl.abort()
  }, [extendedFilter])

  function handleSegmentSelect(slug: SegmentSlug) {
    setActiveSegment(slug)
    const filter = segmentToFilter(slug)
    setExtendedFilter(legacyToExtended(filter))
  }

  function handleAudienceChange(filter: AudienceFilter) {
    setAudienceFilter(filter)
    setExtendedFilter(legacyToExtended(filter))
    setActiveSegment(null)
  }

  async function saveOrUpdate(values: CampaignFormValues): Promise<string> {
    const url = savedId ? `/api/marketing/campaigns/${savedId}` : '/api/marketing/campaigns'
    const method = savedId ? 'PATCH' : 'POST'

    const payload = {
      name: values.name,
      type: 'manual' as const,
      channel: values.channel,
      status: 'draft' as const,
      template_subject: values.template_subject,
      template_body: values.template_body,
      audience_filter: audienceFilter,
      scheduled_at: values.schedule_mode === 'later' && values.scheduled_at
        ? new Date(values.scheduled_at).toISOString()
        : null,
    }

    const res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })

    if (!res.ok) {
      const err: unknown = await res.json()
      const message = typeof err === 'object' && err !== null && 'error' in err
        ? String((err as { error: unknown }).error)
        : 'Failed to save campaign'
      throw new Error(message)
    }

    const json: unknown = await res.json()
    const id = json && typeof json === 'object' && 'data' in json
      ? String((json as { data: { id: string } }).data.id)
      : savedId ?? ''
    return id
  }

  async function onSendScheduleClick(values: CampaignFormValues) {
    setIsSaving(true)
    try {
      const id = await saveOrUpdate(values)
      setSavedId(id)
      onSaved?.(id)
      setShowConfirm(true)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      toast.error(message || 'Failed to save campaign')
    } finally {
      setIsSaving(false)
    }
  }

  async function handleConfirmSend() {
    if (!savedId) return

    const values = watch()
    const url = values.schedule_mode === 'later' && values.scheduled_at
      ? `/api/marketing/campaigns/${savedId}/schedule`
      : `/api/marketing/campaigns/${savedId}/send`

    const res = await fetch(url, { method: 'POST' })
    if (!res.ok) {
      const err: unknown = await res.json()
      const message = typeof err === 'object' && err !== null && 'error' in err
        ? String((err as { error: unknown }).error)
        : 'Failed to send campaign'
      throw new Error(message)
    }

    toast.success(
      values.schedule_mode === 'later'
        ? 'Campaign scheduled'
        : 'Campaign queued to send'
    )

    startTransition(() => {
      router.push('/marketing?tab=campaigns')
      router.refresh()
    })
    onCancel?.()
  }

  const scheduleValue = watch('schedule_mode') === 'later' ? watch('scheduled_at') : undefined
  const ctaLabel = scheduleValue
    ? `Schedule for ${new Date(scheduleValue).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`
    : 'Send now'

  return (
    <>
      <form
        id="campaign-editor-form"
        onSubmit={handleSubmit(onSendScheduleClick)}
        className="space-y-6 pb-24"
      >
        {/* Section 1: Details */}
        <div className="space-y-4">
          <SectionHeading number={1} title="Details" />
          <div className="space-y-1.5">
            <Label htmlFor="campaign-name">Campaign name *</Label>
            <Input
              id="campaign-name"
              placeholder="We miss you — inactive clients"
              autoComplete="off"
              {...register('name')}
            />
            {errors.name && (
              <p className="text-xs text-destructive" role="alert">{errors.name.message}</p>
            )}
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground">Channel:</span>
            <Badge variant="outline" className="text-xs">Email</Badge>
          </div>
        </div>

        <Separator />

        {/* Section 2: Audience */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <SectionHeading number={2} title="Audience" />
            <div className="flex items-center gap-1.5">
              <Users className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
              {countLoading ? (
                <span className="text-xs text-muted-foreground">Calculating…</span>
              ) : (
                <span className="text-xs font-medium text-[color:var(--color-onyx)] tabular-nums">
                  Sending to{' '}
                  <span className="font-semibold">
                    {audienceCount !== null ? audienceCount.toLocaleString() : '—'}
                  </span>{' '}
                  recipient{audienceCount !== 1 ? 's' : ''}
                </span>
              )}
            </div>
          </div>

          <SegmentPresetChips
            activeSlug={activeSegment}
            onSelect={handleSegmentSelect}
          />

          <div className="space-y-2">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-[0.08em]">
              Custom segment
            </p>
            <AudienceFilterBuilder
              value={audienceFilter}
              onChange={handleAudienceChange}
              studioId={studioId}
              locationOptions={locationOptions}
            />
          </div>
        </div>

        <Separator />

        {/* Section 3: Template */}
        <div className="space-y-4">
          <SectionHeading number={3} title="Template" />

          <TemplateGallery
            onSelect={({ subject, body }) => {
              setValue('template_subject', subject)
              setValue('template_body', body)
            }}
          />

          <div className="space-y-1.5">
            <Label htmlFor="campaign-subject">Email subject</Label>
            <Input
              id="campaign-subject"
              placeholder="We miss you, {first_name}!"
              {...register('template_subject')}
            />
          </div>

          <div className="grid gap-4 lg:grid-cols-2">
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Email body</Label>
                <SendTestButton
                  {...(savedId ? { campaignId: savedId } : {})}
                  subject={templateSubject ?? ''}
                  body={templateBody ?? ''}
                />
              </div>
              <Controller
                control={control}
                name="template_body"
                render={({ field }) => (
                  <RichEmailEditor
                    value={field.value ?? ''}
                    onChange={field.onChange}
                    studioId={studioId}
                  />
                )}
              />
            </div>

            <div className="space-y-2">
              <Label className="text-xs text-muted-foreground">Preview</Label>
              <EmailPreview
                subject={templateSubject ?? ''}
                body={templateBody ?? ''}
              />
            </div>
          </div>
        </div>

        <Separator />

        {/* Section 4: Schedule */}
        <div className="space-y-4">
          <SectionHeading number={4} title="Schedule" />

          <Controller
            control={control}
            name="schedule_mode"
            render={({ field }) => (
              <RadioGroup
                value={field.value}
                onValueChange={field.onChange}
                className="flex flex-col gap-2"
              >
                <label className="flex items-center gap-3 cursor-pointer">
                  <RadioGroupItem value="now" id="schedule-now" />
                  <div>
                    <span className="text-sm font-medium text-foreground">Send now</span>
                    <p className="text-xs text-muted-foreground">Campaign will queue immediately after confirmation</p>
                  </div>
                </label>
                <label className="flex items-center gap-3 cursor-pointer">
                  <RadioGroupItem value="later" id="schedule-later" />
                  <div>
                    <span className="text-sm font-medium text-foreground">Schedule for later</span>
                    <p className="text-xs text-muted-foreground">Pick a date and time</p>
                  </div>
                </label>
              </RadioGroup>
            )}
          />

          {scheduleMode === 'later' && (
            <div className="space-y-1.5 ml-6">
              <Label htmlFor="scheduled-at">Send at</Label>
              <Input
                id="scheduled-at"
                type="datetime-local"
                {...register('scheduled_at')}
              />
              {studioTimezone && (
                <p className="text-xs text-muted-foreground">
                  Studio time ({studioTimezone})
                </p>
              )}
            </div>
          )}

          <div className="flex items-center gap-3">
            <Controller
              control={control}
              name="is_recurring"
              render={({ field }) => (
                <Switch
                  id="is-recurring"
                  checked={field.value}
                  onCheckedChange={field.onChange}
                />
              )}
            />
            <Label htmlFor="is-recurring" className="cursor-pointer">Recurring campaign</Label>
          </div>

          {isRecurring && (
            <div className="ml-6 space-y-1.5">
              <Label>Repeat</Label>
              <Controller
                control={control}
                name="recurrence_interval"
                render={({ field }) => (
                  <Select value={field.value} onValueChange={field.onChange}>
                    <SelectTrigger className="w-40">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="daily">Daily</SelectItem>
                      <SelectItem value="weekly">Weekly</SelectItem>
                      <SelectItem value="monthly">Monthly</SelectItem>
                    </SelectContent>
                  </Select>
                )}
              />
              <p className="text-xs text-muted-foreground">
                Recurrence stored as RRULE — full scheduling in Sprint M6 worker.
              </p>
            </div>
          )}
        </div>
      </form>

      {/* Sticky footer */}
      <div className="fixed bottom-0 left-0 right-0 border-t bg-[color:var(--color-bone)] px-6 py-3 flex items-center justify-between gap-3 z-10 shadow-soft-md">
        <Button
          type="button"
          variant="outline"
          onClick={() => {
            onCancel?.()
            if (!onCancel) router.back()
          }}
        >
          Cancel
        </Button>

        <Button
          type="submit"
          form="campaign-editor-form"
          disabled={isSaving}
          className="bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/90 min-w-[120px]"
        >
          {isSaving ? 'Saving…' : ctaLabel}
        </Button>
      </div>

      <CampaignConfirmDialog
        open={showConfirm}
        onOpenChange={setShowConfirm}
        campaignId={savedId}
        campaignName={watch('name')}
        subject={watch('template_subject') ?? ''}
        recipientCount={audienceCount}
        scheduledAt={watch('schedule_mode') === 'later' ? (watch('scheduled_at') ?? null) : null}
        bodyHtml={watch('template_body') ?? ''}
        onConfirm={handleConfirmSend}
      />
    </>
  )
}

'use client'

/**
 * CampaignDrawer — global campaign creation / edit sheet.
 *
 * Opens on ?campaign=new or ?campaign=<id>.
 * Closes on Esc / overlay / Cancel — strips query param from URL.
 * shadcn Sheet handles focus trap and Esc key natively.
 */

import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { CampaignEditor } from './CampaignEditor'
import type { ComponentProps } from 'react'

type EditorOptionalProps = Pick<ComponentProps<typeof CampaignEditor>, 'studioTimezone' | 'studioName' | 'campaignId'>

interface CampaignDrawerProps {
  studioId: string
  studioTimezone?: string
  studioName?: string
  locationOptions?: Array<{ id: string; name: string }>
}

export function CampaignDrawer({
  studioId,
  studioTimezone,
  studioName,
  locationOptions = [],
}: CampaignDrawerProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const campaignParam = searchParams.get('campaign')

  const isOpen = campaignParam === 'new' || (!!campaignParam && campaignParam !== 'new')
  const isEdit = isOpen && campaignParam !== 'new'

  function closeDrawer() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('campaign')
    params.delete('segment')
    const qs = params.toString()
    router.replace(qs ? `${pathname}?${qs}` : pathname)
  }

  function handleSaved(id: string) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', id)
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  // Build optional props without assigning undefined — exactOptionalPropertyTypes safe
  const optionalProps: EditorOptionalProps = {}
  if (isEdit && campaignParam) optionalProps.campaignId = campaignParam
  if (studioTimezone) optionalProps.studioTimezone = studioTimezone
  if (studioName) optionalProps.studioName = studioName

  return (
    <Sheet open={isOpen} onOpenChange={(open) => { if (!open) closeDrawer() }}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-[48rem] overflow-y-auto bg-[color:var(--color-bone)] p-0 shadow-soft-md"
        aria-describedby="campaign-drawer-desc"
      >
        <div className="sticky top-0 z-10 border-b bg-[color:var(--color-bone)] px-6 py-4">
          <SheetHeader>
            <SheetTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
              {isEdit ? 'Edit campaign' : 'New campaign'}
            </SheetTitle>
            <SheetDescription id="campaign-drawer-desc" className="text-xs text-[color:var(--color-stone)]">
              Fill out all sections below, then confirm to send or schedule.
            </SheetDescription>
          </SheetHeader>
        </div>

        <div className="px-6 pt-4 pb-32 relative">
          <CampaignEditor
            key={campaignParam ?? 'new'}
            {...optionalProps}
            studioId={studioId}
            locationOptions={locationOptions}
            mode={isEdit ? 'edit' : 'create'}
            onSaved={handleSaved}
            onCancel={closeDrawer}
          />
        </div>
      </SheetContent>
    </Sheet>
  )
}

