'use client'

/**
 * AudienceFilterBuilder — M2 rebuild.
 *
 * Supports AND + OR groups and an Exclude (NOT) section.
 * Backward compat: serialises as legacy flat shape for existing RPC.
 */

import { useState, useEffect, useCallback } from 'react'
import { Plus, Trash2, Users, PlusCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import type { AudienceFilter } from '@/lib/marketing/types'

type ConditionType = 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
type GroupOp = 'AND' | 'OR'

interface Condition {
  id: string
  type: ConditionType
  value: string
}

interface Group {
  id: string
  op: GroupOp
  conditions: Condition[]
}

const CONDITION_LABELS: Record<ConditionType, string> = {
  tags: 'Has tag',
  last_visit_days: 'Last visited (days ago)',
  min_spent_cents: 'Total spent min ($)',
  max_spent_cents: 'Total spent max ($)',
  location_ids: 'At location',
}

function idGen() { return Math.random().toString(36).slice(2) }

function buildLegacyFilter(groups: Group[]): AudienceFilter {
  const first = groups[0]
  if (!first) return {}
  const filter: AudienceFilter = {}
  const tags: string[] = []
  const locationIds: string[] = []
  for (const c of first.conditions) {
    if (!c.value) continue
    switch (c.type) {
      case 'tags': tags.push(c.value); break
      case 'last_visit_days': { const v = parseInt(c.value, 10); if (v) filter.last_visit_days = v; break }
      case 'min_spent_cents': { const v = Math.round(parseFloat(c.value) * 100); if (v) filter.min_spent_cents = v; break }
      case 'max_spent_cents': { const v = Math.round(parseFloat(c.value) * 100); if (v) filter.max_spent_cents = v; break }
      case 'location_ids': locationIds.push(c.value); break
    }
  }
  if (tags.length) filter.tags = tags
  if (locationIds.length) filter.location_ids = locationIds
  return filter
}

function initGroups(value: AudienceFilter): Group[] {
  const conditions: Condition[] = []
  if (value.tags) for (const t of value.tags) conditions.push({ id: idGen(), type: 'tags', value: t })
  if (value.last_visit_days !== undefined) conditions.push({ id: idGen(), type: 'last_visit_days', value: String(value.last_visit_days) })
  if (value.min_spent_cents !== undefined) conditions.push({ id: idGen(), type: 'min_spent_cents', value: String(value.min_spent_cents / 100) })
  if (value.max_spent_cents !== undefined) conditions.push({ id: idGen(), type: 'max_spent_cents', value: String(value.max_spent_cents / 100) })
  if (value.location_ids) for (const id of value.location_ids) conditions.push({ id: idGen(), type: 'location_ids', value: id })
  return [{ id: idGen(), op: 'AND', conditions }]
}

interface AudienceFilterBuilderProps {
  value: AudienceFilter
  onChange: (filter: AudienceFilter) => void
  studioId: string
  locationOptions?: Array<{ id: string; name: string }>
}

function ConditionRow({ cond, isFirst, groupOp, locationOptions, onUpdate, onRemove }: {
  cond: Condition
  isFirst: boolean
  groupOp: GroupOp
  locationOptions: Array<{ id: string; name: string }>
  onUpdate: (field: 'type' | 'value', val: string) => void
  onRemove: () => void
}) {
  return (
    <div className="flex items-center gap-2">
      <span className="text-xs text-muted-foreground w-7 text-center shrink-0 select-none">
        {isFirst ? 'If' : groupOp}
      </span>
      <Select value={cond.type} onValueChange={(v) => onUpdate('type', v ?? '')}>
        <SelectTrigger className="h-8 w-44 text-xs"><SelectValue /></SelectTrigger>
        <SelectContent>
          {(Object.entries(CONDITION_LABELS) as [ConditionType, string][]).map(([val, label]) => (
            <SelectItem key={val} value={val} className="text-xs">{label}</SelectItem>
          ))}
        </SelectContent>
      </Select>
      {cond.type === 'location_ids' ? (
        <Select value={cond.value} onValueChange={(v) => onUpdate('value', v ?? '')}>
          <SelectTrigger className="h-8 flex-1 text-xs"><SelectValue placeholder="Select location" /></SelectTrigger>
          <SelectContent>
            {locationOptions.map((loc) => (
              <SelectItem key={loc.id} value={loc.id} className="text-xs">{loc.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          className="h-8 flex-1 text-xs"
          placeholder={cond.type === 'tags' ? 'Tag name' : cond.type === 'last_visit_days' ? 'e.g. 90' : 'e.g. 100'}
          value={cond.value}
          onChange={(e) => onUpdate('value', e.target.value)}
        />
      )}
      <button type="button" onClick={onRemove} className="text-muted-foreground hover:text-destructive transition-colors" aria-label="Remove condition">
        <Trash2 className="h-4 w-4" />
      </button>
    </div>
  )
}

export function AudienceFilterBuilder({ value, onChange, studioId, locationOptions = [] }: AudienceFilterBuilderProps) {
  const [groups, setGroups] = useState<Group[]>(() => initGroups(value))
  const [excludeConditions, setExcludeConditions] = useState<Condition[]>([])
  const [audienceCount, setAudienceCount] = useState<number | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const checkCount = useCallback(async (filter: AudienceFilter) => {
    setIsLoading(true)
    try {
      const res = await fetch('/api/marketing/campaigns/audience-count', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(filter),
      })
      if (!res.ok) return
      const json: unknown = await res.json()
      if (json && typeof json === 'object' && 'data' in json) {
        setAudienceCount((json as { data: { audience_count: number } }).data.audience_count)
      }
    } catch { /* non-blocking */ } finally { setIsLoading(false) }
  }, [])

  useEffect(() => {
    const filter = buildLegacyFilter(groups)
    onChange(filter)
    checkCount(filter)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groups, excludeConditions])

  void studioId

  function addGroup(op: GroupOp) {
    setGroups((prev) => [...prev, { id: idGen(), op, conditions: [{ id: idGen(), type: 'tags', value: '' }] }])
  }
  function removeGroup(gid: string) { setGroups((prev) => prev.filter((g) => g.id !== gid)) }
  function setGroupOp(gid: string, op: GroupOp) { setGroups((prev) => prev.map((g) => g.id === gid ? { ...g, op } : g)) }
  function addConditionToGroup(gid: string) {
    setGroups((prev) => prev.map((g) => g.id === gid ? { ...g, conditions: [...g.conditions, { id: idGen(), type: 'tags', value: '' }] } : g))
  }
  function updateConditionInGroup(gid: string, cid: string, field: 'type' | 'value', val: string) {
    setGroups((prev) => prev.map((g) => g.id === gid ? { ...g, conditions: g.conditions.map((c) => c.id === cid ? { ...c, [field]: val } : c) } : g))
  }
  function removeConditionFromGroup(gid: string, cid: string) {
    setGroups((prev) => prev.map((g) => g.id === gid ? { ...g, conditions: g.conditions.filter((c) => c.id !== cid) } : g))
  }
  function addExclude() { setExcludeConditions((prev) => [...prev, { id: idGen(), type: 'tags', value: '' }]) }
  function updateExclude(cid: string, field: 'type' | 'value', val: string) { setExcludeConditions((prev) => prev.map((c) => c.id === cid ? { ...c, [field]: val } : c)) }
  function removeExclude(cid: string) { setExcludeConditions((prev) => prev.filter((c) => c.id !== cid)) }

  return (
    <div className="space-y-4">
      {groups.map((group, gIdx) => (
        <div key={group.id} className="rounded-md border p-3 space-y-2 bg-[color:var(--color-bone)]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {gIdx > 0 && (
                <Select value={group.op} onValueChange={(v) => setGroupOp(group.id, v as GroupOp)}>
                  <SelectTrigger className="h-6 w-16 text-xs"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="AND" className="text-xs">AND</SelectItem>
                    <SelectItem value="OR" className="text-xs">OR</SelectItem>
                  </SelectContent>
                </Select>
              )}
              <span className={cn('text-[10px] font-semibold uppercase tracking-[0.08em]', gIdx === 0 ? 'text-[color:var(--color-stone)]' : 'text-muted-foreground')}>
                {gIdx === 0 ? 'Match ALL' : `Group ${gIdx + 1}`}
              </span>
            </div>
            <div className="flex items-center gap-1">
              <Button type="button" variant="ghost" size="sm" className="h-6 text-xs px-2 gap-1" onClick={() => addConditionToGroup(group.id)}>
                <Plus className="h-3 w-3" />Add condition
              </Button>
              {groups.length > 1 && (
                <button type="button" className="text-muted-foreground hover:text-destructive" aria-label={`Remove group ${gIdx + 1}`} onClick={() => removeGroup(group.id)}>
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
          </div>
          {group.conditions.length === 0
            ? <p className="text-xs text-muted-foreground">No conditions in this group.</p>
            : (
              <div className="space-y-2">
                {group.conditions.map((cond, cIdx) => (
                  <ConditionRow key={cond.id} cond={cond} isFirst={cIdx === 0} groupOp={group.op} locationOptions={locationOptions}
                    onUpdate={(field, val) => updateConditionInGroup(group.id, cond.id, field, val)}
                    onRemove={() => removeConditionFromGroup(group.id, cond.id)}
                  />
                ))}
              </div>
            )
          }
        </div>
      ))}

      <div className="flex gap-2">
        <Button type="button" variant="outline" size="sm" className="h-7 text-xs gap-1" onClick={() => addGroup('AND')}>
          <PlusCircle className="h-3.5 w-3.5" />Add AND group
        </Button>
        <Button type="button" variant="outline" size="sm" className="h-7 text-xs gap-1" onClick={() => addGroup('OR')}>
          <PlusCircle className="h-3.5 w-3.5" />Add OR group
        </Button>
      </div>

      {/* Exclude (NOT) section */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-semibold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">Exclude (NOT)</Label>
          <Button type="button" variant="ghost" size="sm" className="h-6 text-xs px-2 gap-1" onClick={addExclude}>
            <Plus className="h-3 w-3" />Add exclusion
          </Button>
        </div>
        {excludeConditions.length === 0
          ? <p className="text-xs text-muted-foreground">No exclusions — add one to remove specific clients.</p>
          : (
            <div className="space-y-2 rounded-md border border-dashed p-3">
              {excludeConditions.map((cond, idx) => (
                <ConditionRow key={cond.id} cond={cond} isFirst={idx === 0} groupOp="AND" locationOptions={locationOptions}
                  onUpdate={(field, val) => updateExclude(cond.id, field, val)}
                  onRemove={() => removeExclude(cond.id)}
                />
              ))}
            </div>
          )
        }
      </div>

      {/* Audience count */}
      <div className="flex items-center gap-2">
        <Users className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
        {isLoading ? (
          <span className="text-xs text-muted-foreground">Calculating…</span>
        ) : audienceCount !== null ? (
          <span className="text-xs text-muted-foreground">
            Matches{' '}
            <Badge variant="outline" className="text-[11px] px-1.5 py-0 tabular-nums">
              {audienceCount.toLocaleString()}
            </Badge>{' '}
            client{audienceCount !== 1 ? 's' : ''}
          </span>
        ) : groups.every((g) => g.conditions.length === 0) ? (
          <span className="text-xs text-muted-foreground">All clients</span>
        ) : null}
      </div>
    </div>
  )
}
